good_example:
public function resolve($a, $b, $c): int
{
    if ($a && $b) {
        return 1;
    }
    if ($a && $c) {
        return 2;
    }
    if ($a || $c) {
        return 3;
    }
    if (!$a) {
        return 4;
    }
    return 0;
}
